import math

def calculate_a_n(n):
    # a_n = 6^n + 2^n + 3^n - 1
    return 6**n + 2**n + 3**n - 1

primes = [7, 11, 13, 17, 19]
N = 20
results = {}

for p in primes:
    all_divisible = True
    for n in range(1, N + 1):
        a_n = calculate_a_n(n)
        if a_n % p != 0:
            all_divisible = False
            break

    if all_divisible:
        results[p] = True
    else:
        results[p] = False

print(f"Check for primes p < 20 (excluding 2, 5) dividing all 20 terms of a_n:")
for p, result in results.items():
    print(f"Prime {p}: Divides all 20 terms? {result}")

